                    .isAfter(settledOn.plusDays(ClaimStatus.VOID_SETTLED_DAYS))) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within "
                        + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
