# GET /api/sheets/{sheetId}/claims — every claim on the sheet, newest first.
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithClaims {
    public void respond(@PathVariable("sheetId") String sheetId, Claims claims, ClaimLocks locks,
            ObjectResponse<List<ClaimResponse>> response) {
        java.util.Map<Long, List<String>> logs = claims.logs(sheetId.trim());
        java.util.Map<Long, List<String>> comments = claims.comments(sheetId.trim());
        java.util.Map<Long, String> locked = locks.list(sheetId.trim());
        response.send(claims.list(sheetId.trim()).stream()
                .map(c -> ClaimResponse.from(c, logs.getOrDefault(c.id(), List.of())).withLockedBy(locked.get(c.id()))
                        .withComments(comments.getOrDefault(c.id(), List.of())))
                .toList());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSheet {
    public void respond(@Val Sheet sheet, ObjectResponse<SheetResponse> response) {
        response.send(SheetResponse.from(sheet));
    }
}
package net.officefloor.hq.app.sheet;

/** The sheet as the screen sees it. {@code today} is ISO yyyy-MM-dd. */
public record SheetResponse(String id, String today, boolean archived) {

    public static SheetResponse from(Sheet sheet) {
        return new SheetResponse(sheet.id(), sheet.today().toString(), sheet.archived());
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSheet {
    // A sheet that was never loaded before starts empty, so any id loads.
    public void load(@PathVariable("sheetId") String sheetId, Sheets sheets, Out<Sheet> sheetOut) {
        sheetOut.set(sheets.find(sheetId.trim()));
    }
}
import { ClaimCells } from '../../slots/defs/claimColumns';
import type { Claim } from './claimsQuery';

/** Who opened the claim (blank until it is opened). */
function ClaimOpenedBy({ claim }: { sheetId: string; claim: Claim }) {
  return <td data-testid="claim-opened-by">{claim.openedBy ?? ''}</td>;
}

export const contribution = ClaimCells.fill({ order: 25, Component: ClaimOpenedBy });
import { getJson } from '../../api/http';

/** `today` is the sheet's own date (yyyy-mm-dd): use it, never the real clock, for anything dated.
 *  An `archived` sheet shows everything and refuses every change. */
export type Sheet = { id: string; today: string; archived: boolean };

/** Every query kept per sheet lives under this key, so re-loading a sheet re-reads all of it. */
export const sheetKey = (sheetId: string) => ['sheet', sheetId] as const;

export const sheetQuery = (sheetId: string) => ({
  queryKey: sheetKey(sheetId),
  queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
});

